/**
 * Build the `.hornscribe.json` project document (schema v1, FND-001)
 * for the プロジェクトを保存 command (#100).
 *
 * The worker's `project.save` validates this through
 * HornScribeProject.from_dict before writing, so every id here must
 * already satisfy the domain regexes (prj-/rev-/tr-/sn-). Fields the
 * schema does not know (scoreDocument, musicXmlConcert, musicXmlHornF,
 * reviewIssues) ride along as extra keys — preserved verbatim, ignored
 * by the v1 validator, and the data a future project-open restore
 * needs to reconstruct the score without re-transcribing.
 */
import type { LoadedAudio } from "./types";
import type { ScoreDocumentPort } from "../score/document";

/** Fields the app knows at save time. */
export interface ProjectSaveInput {
  readonly audio: LoadedAudio | null;
  readonly doc: ScoreDocumentPort;
  /** Completed job result payload (meta/reviewIssues/scoreDocument). */
  readonly result: unknown;
  /** #222: when re-saving an opened project, keep its identity — a
   *  fresh save derives a new prj- id from the source identity. */
  readonly projectId?: string | null;
  /** #265: the project's recorded source ref — the fallback when no
   *  audio is loaded (SOURCE_MISSING save must not erase the
   *  originalPath/contentHash a later relink verifies against). */
  readonly priorSourceAudio?: {
    originalPath: string;
    contentHash: string;
  } | null;
}

/** `prj-<16hex>` — deterministic content-derived id (ids.py contract). */
export async function deriveProjectId(seed: unknown): Promise<string> {
  // Callers pass a flat object built in fixed key order — plain
  // stringify is deterministic here (same policy as ids.py's canonical
  // JSON digest, minus key sorting which a flat fixed-order object
  // does not need).
  const blob = JSON.stringify(seed);
  const digest = await crypto.subtle.digest(
    "SHA-256",
    new TextEncoder().encode(blob),
  );
  const hex = [...new Uint8Array(digest)]
    .map((b) => b.toString(16).padStart(2, "0"))
    .join("");
  return `prj-${hex.slice(0, 16)}`;
}

function resultMeta(result: unknown): Record<string, unknown> {
  if (typeof result !== "object" || result === null) return {};
  const meta = (result as Record<string, unknown>).meta;
  return typeof meta === "object" && meta !== null
    ? (meta as Record<string, unknown>)
    : {};
}

/** Source ref for the audio backing this score (path-backed only —
 *  browser-dev File refs have no durable path to record). */
function sourceAudioOf(audio: LoadedAudio | null): {
  originalPath: string;
  contentHash: string;
} | null {
  if (!audio) return null;
  const ref = audio.ref;
  if (ref.kind === "path") {
    return { originalPath: ref.path, contentHash: ref.contentHash ?? "" };
  }
  if (ref.kind === "recording" && ref.path) {
    return { originalPath: ref.path, contentHash: ref.contentHash ?? "" };
  }
  return null;
}

const PROJECT_ID_RE = /^prj-[0-9a-f]{16}$/;
const REVISION_RE = /^rev-[0-9a-f]{16}$/;
const TRANSCRIPTION_RE = /^tr-[0-9a-f]{16}$/;
const SCORE_NOTE_RE = /^sn-\d{6}$/;

/** True when the document's ids satisfy the v1 schema — a fixture/dev
 *  document (rev-fixture*) cannot be saved and the command should say
 *  so honestly instead of shipping an invalid file. */
export function isSaveableRevision(revisionId: string): boolean {
  return REVISION_RE.test(revisionId);
}

/**
 * Assemble the schema-v1 document. Returns null when the score cannot
 * be represented (non-schema revision id — e.g. the dev fixture doc).
 */
export async function buildProjectDocument(
  input: ProjectSaveInput,
): Promise<Record<string, unknown> | null> {
  const { audio, doc, result } = input;
  if (!isSaveableRevision(doc.revisionId)) return null;
  const meta = resultMeta(result);
  // #243: the engine already streamed a SHA-256 of the source into
  // the canonical payload — prefer that provenance over re-hashing
  // the browser-held bytes a second time.
  const canonical = doc.canonicalDocument?.() as
    Record<string, unknown> | undefined;
  const canonicalHash =
    typeof canonical?.sourceAudioHash === "string"
      ? (canonical.sourceAudioHash as string)
      : null;
  const sourceAudio = sourceAudioOf(audio);
  // #243: never write an empty contentHash — a project saved without
  // a verified source identity cannot reopen or relink. Prefer the
  // engine-recorded hash, then the import-time hash; if neither
  // exists the sourceAudio block is omitted rather than written
  // invalid.
  const sourceAudioResolved =
    sourceAudio == null
      ? // #265: no audio loaded (SOURCE_MISSING) — keep the project's
        // recorded ref so a save does not erase the relink target.
        input.priorSourceAudio &&
        (canonicalHash ?? input.priorSourceAudio.contentHash)
        ? {
            originalPath: input.priorSourceAudio.originalPath,
            contentHash: (canonicalHash ??
              input.priorSourceAudio.contentHash) as string,
          }
        : null
      : (canonicalHash ?? sourceAudio.contentHash)
        ? {
            originalPath: sourceAudio.originalPath,
            contentHash: (canonicalHash ?? sourceAudio.contentHash) as string,
          }
        : null;

  const transcriptionRevision = meta.transcriptionRevision;
  const transcription =
    typeof transcriptionRevision === "string" &&
    TRANSCRIPTION_RE.test(transcriptionRevision)
      ? {
          backend: String(meta.backend ?? "unknown"),
          backendVersion: String(meta.backendVersion ?? "unknown"),
          settings:
            typeof meta.settings === "object" && meta.settings !== null
              ? meta.settings
              : {},
          revision: transcriptionRevision,
        }
      : null;

  // Canonical-note edits → schema UserEdit records. pitchDelta and
  // deleted are independent facets, so one UI edit can emit two rows.
  const userEdits: Record<string, unknown>[] = [];
  let editSeq = 0;
  for (const [noteId, edit] of doc.noteEdits()) {
    if (!SCORE_NOTE_RE.test(noteId)) continue;
    if (edit.pitchDelta !== 0) {
      userEdits.push({
        id: `ue-${String(++editSeq).padStart(4, "0")}`,
        scoreRevision: doc.revisionId,
        kind: "pitch_change",
        targetNoteIds: [noteId],
        payload: { semitones: edit.pitchDelta },
      });
    }
    if (edit.deleted) {
      userEdits.push({
        id: `ue-${String(++editSeq).padStart(4, "0")}`,
        scoreRevision: doc.revisionId,
        kind: "delete",
        targetNoteIds: [noteId],
        payload: {},
      });
    } else if (doc.canonicalNoteDeleted?.(noteId)) {
      // #224: an overlay restore on a canonical-deleted note — without
      // this row the saved project would silently keep the delete.
      userEdits.push({
        id: "ue-" + String(++editSeq).padStart(4, "0"),
        scoreRevision: doc.revisionId,
        kind: "restore",
        targetNoteIds: [noteId],
        payload: {},
      });
    }
  }

  const reviewDecisions = doc
    .reviewIssues()
    .filter((i) => i.status !== "open")
    .map((i) => ({
      issueId: i.id,
      scoreRevision: doc.revisionId,
      status: i.status,
      note: null,
    }));

  // #222: a project's identity is its source, not the current score
  // revision — edits must not mint a new project id. Re-saving an
  // opened project keeps its recorded id verbatim.
  const projectId =
    input.projectId ??
    (await deriveProjectId({
      audioPath: sourceAudioResolved?.originalPath ?? null,
      audioHash: sourceAudioResolved?.contentHash ?? null,
      title: doc.meta.title,
    }));

  const resultObj =
    typeof result === "object" && result !== null
      ? (result as Record<string, unknown>)
      : {};

  return {
    schemaVersion: 1,
    projectId,
    sourceAudio: sourceAudioResolved,
    transcription,
    score: {
      revision: doc.revisionId,
      quantizationSettings:
        typeof meta.settings === "object" && meta.settings !== null
          ? meta.settings
          : {},
    },
    userEdits,
    reviewDecisions,
    uiSession: null,
    // --- preserved extras (ignored by the v1 validator) ---
    // #115: the LIVE canonical payload — after an engine rhythm edit the
    // document's scoreDocument is newer than the job result's, and saving
    // the stale one would lose the edit on reopen (the XMLs below are
    // already the edited bodies).
    scoreDocument: doc.canonicalDocument?.() ?? resultObj.scoreDocument ?? null,
    reviewIssues: doc.reviewIssues(),
    // #360: still-deferred cap-omitted issues persist verbatim —
    //  expanded ones already ride inside reviewIssues above (with
    //  their decisions), so reopening never loses either half.
    omittedReviewIssues:
      doc.deferredReviewIssues?.() ??
      (Array.isArray(resultObj.omittedReviewIssues)
        ? resultObj.omittedReviewIssues
        : []),
    musicXmlConcert: doc.musicXml("concert"),
    musicXmlHornF: doc.musicXml("hornF"),
    meta,
  };
}

/* ---------------------- shell-side validation (#389) ----------------------
 * Manual save no longer round-trips through the Python worker, so the
 * shell path carries its own copy of HornScribeProject.from_dict's
 * checks (model.py): schema version, id regexes, and the required-key
 * shape of each nested record. Returns a short reason string, or null
 * when the document is safe to write. Fail closed: any reason aborts
 * the save before a byte reaches disk. */

function isRecord(v: unknown): v is Record<string, unknown> {
  return typeof v === "object" && v !== null;
}

/** The schema-v1 check shared by manual save and autosave (#389). */
export function validateProjectDocument(project: unknown): string | null {
  if (!isRecord(project)) return "project document is not an object";
  const version = project.schemaVersion;
  if (version == null) return "missing required field: schemaVersion";
  if (!Number.isInteger(version)) return "schemaVersion must be an integer";
  if (version !== 1) return `unsupported schemaVersion ${version}`;
  const pid = project.projectId;
  if (typeof pid !== "string" || !PROJECT_ID_RE.test(pid)) {
    return "projectId is missing or malformed";
  }
  const source = project.sourceAudio;
  if (source != null) {
    if (!isRecord(source)) return "sourceAudio is malformed";
    if (
      typeof source.originalPath !== "string" ||
      typeof source.contentHash !== "string"
    ) {
      return "sourceAudio.originalPath/contentHash are required";
    }
  }
  const transcription = project.transcription;
  if (transcription != null) {
    if (!isRecord(transcription)) return "transcription is malformed";
    if (
      typeof transcription.backend !== "string" ||
      typeof transcription.backendVersion !== "string" ||
      typeof transcription.revision !== "string"
    ) {
      return "transcription fields are missing or malformed";
    }
    if (!TRANSCRIPTION_RE.test(transcription.revision)) {
      return "transcription.revision is malformed";
    }
  }
  const score = project.score;
  if (score != null) {
    if (!isRecord(score)) return "score is malformed";
    if (
      typeof score.revision !== "string" ||
      !REVISION_RE.test(score.revision)
    ) {
      return "score.revision is malformed";
    }
  }
  const userEdits = project.userEdits;
  if (userEdits != null && !Array.isArray(userEdits)) {
    return "userEdits must be an array";
  }
  for (const e of userEdits ?? []) {
    if (!isRecord(e)) return "userEdits[] entries must be objects";
    if (
      typeof e.id !== "string" ||
      typeof e.kind !== "string" ||
      typeof e.scoreRevision !== "string" ||
      !REVISION_RE.test(e.scoreRevision)
    ) {
      return "userEdits[].scoreRevision is malformed";
    }
    const ids = e.targetNoteIds;
    if (!Array.isArray(ids)) {
      return "userEdits[].targetNoteIds must be an array";
    }
    for (const n of ids) {
      if (typeof n !== "string" || !SCORE_NOTE_RE.test(n)) {
        return "userEdits[].targetNoteIds contains malformed ID";
      }
    }
  }
  const decisions = project.reviewDecisions;
  if (decisions != null && !Array.isArray(decisions)) {
    return "reviewDecisions must be an array";
  }
  for (const d of decisions ?? []) {
    if (!isRecord(d)) return "reviewDecisions[] entries must be objects";
    if (
      typeof d.issueId !== "string" ||
      typeof d.status !== "string" ||
      typeof d.scoreRevision !== "string" ||
      !REVISION_RE.test(d.scoreRevision)
    ) {
      return "reviewDecisions[].scoreRevision is malformed";
    }
  }
  return null;
}

/** Validate then write through the injected seam — the shared
 *  engine-free save path (#389). `write` is `project_write` in prod;
 *  an invalid document throws before `write` is ever called (fail
 *  closed) and the serialized body is the same JSON.stringify contract
 *  the autosave path writes. */
export async function writeProjectDocument<R>(
  path: string,
  project: Record<string, unknown>,
  write: (path: string, contents: string) => Promise<R>,
): Promise<R> {
  const invalid = validateProjectDocument(project);
  if (invalid != null) {
    throw new Error(`invalid project document: ${invalid}`);
  }
  return write(path, JSON.stringify(project));
}

/**
 * 要確認 review header (UI-050, GUI_UX_SPEC §12).
 *
 * Spec header: 「要確認 n / total」＋ [前へ] [元音源を再生] [問題なし]
 * [次へ]. The P4 prototype's validated flow is productionized here: every
 * action is a real button (Tab/Enter reachable) AND a registry-bound
 * shortcut shown in the tooltip — 20+ items are processable without ever
 * opening a menu.
 *
 * Visual rule (issue body + §12/§15): the review state is expressed by a
 * text badge (要確認 + severity label), the reason's Japanese title/detail
 * and the position counter — never by color alone and never by a raw
 * confidence number (モデル確信度 is shown only as labelled evidence).
 */
import { ja } from "../strings/ja";
import type { RefObject } from "react";
import { HsButton } from "../components/primitives/Button";
import { HsTooltip } from "../components/primitives/Tooltip";
import { issueConfidence, type ScoreReviewIssue } from "./review";
import { List24Regular } from "@fluentui/react-icons";

export interface ReviewBarCopy {
  reasonTitle: string;
  reasonDetail: string;
  severityLabel: string;
  statusLabel: string;
}

export interface ReviewBarProps {
  /** Current cursor (0-based) into the full issue list. */
  readonly index: number;
  /** Total issues in this revision's list. */
  readonly total: number;
  /** Issues still open. */
  readonly pending: number;
  /** #272: issues the engine detected but the surfacing cap omitted —
   *  shown so a truncated list is never silent (0 = hide). */
  readonly omitted?: number;
  // #360: expanding the omitted tail — when the document can supply
  //  the deferred issues, the count turns into a one-click 展開.
  onExpandOmitted?(): void;
  readonly issue: ScoreReviewIssue | null;
  readonly copy: ReviewBarCopy | null;
  /** True when the focused issue's primary note is currently deleted. */
  readonly noteDeleted: boolean;
  readonly canUndo: boolean;
  readonly canRedo: boolean;
  /** Note-edit capability: false on whole-piece issues (meter_conflict,
   *  monophonic_backend, ...) where pitch +/- and delete would be silent
   *  no-ops. Buttons stay visible but disabled with an explanation. */
  readonly canEditNotes: boolean;
  /** False when the issue has no audible range to loop. */
  readonly canPlaySource: boolean;
  /** Optional one-click remedy for issues that carry a direct fix
   *  (built by buildReviewAction - label, tooltip and handler always
   *  come from the same decision). */
  readonly action?: {
    readonly label: string;
    readonly tooltip: string;
    run(): void;
  } | null;
onPrev(): void;
onNext(): void;
  /** #361: the ReviewNavigator popover — 一覧 opens/closes it; the
   *  button stays a toggle (aria-pressed mirrors the open state). */
  readonly navigatorOpen: boolean;
  onToggleNavigator(): void;
  /** Focus lands back here when the navigator closes (Esc / jump). */
  readonly navigatorButtonRef?: RefObject<HTMLButtonElement>;
onPlaySource(): void;
  onAccept(): void;
  onDismiss(): void;
  onPitch(delta: number): void;
  onDeleteOrRestore(): void;
  onUndo(): void;
  onRedo(): void;
  onExit(): void;
}

function withKey(label: string, key: string): string {
  return `${label}（${key}）`;
}

export function ReviewBar({
  index,
  total,
  pending,
  omitted = 0,
  onExpandOmitted,
  issue,
  copy,
  noteDeleted,
  canUndo,
  canRedo,
  canEditNotes,
  canPlaySource,
  action = null,
  onPrev,
  onNext,
  navigatorOpen,
  onToggleNavigator,
  navigatorButtonRef,
  onPlaySource,
  onAccept,
  onDismiss,
  onPitch,
  onDeleteOrRestore,
  onUndo,
  onRedo,
  onExit,
}: ReviewBarProps) {
  const r = ja.review;
  const allDone = pending === 0;
  const confidence = issue ? issueConfidence(issue) : null;
  // Note-edit buttons on a whole-piece issue get the reason tooltip so
  // the disabled state explains itself (shortcut key suffix omitted -
  // the shortcut is inert too).
  const noteEditTip = (label: string, key: string) =>
    canEditNotes ? withKey(label, key) : r.noteTargetRequired;
  return (
    <div
      className="hs-score-reviewbar"
      role="region"
      aria-label={r.regionLabel}
    >
      <div className="hs-score-reviewbar__row hs-score-reviewbar__row--status">
        <strong className="hs-score-reviewbar__position" aria-live="polite">
          {allDone ? r.allDone : r.position(index + 1, total)}
        </strong>
        {!allDone && (
          <span className="hs-score-reviewbar__remaining">
            {r.remaining(pending)}
          </span>
        )}
        {omitted > 0 && (
          onExpandOmitted ? (
            <button
              type="button"
              className="hs-score-reviewbar__omitted hs-score-reviewbar__omitted--action"
              onClick={onExpandOmitted}
            >
              {r.expandOmitted(omitted)}
            </button>
          ) : (
            <span className="hs-score-reviewbar__omitted">
              {r.omitted(omitted)}
            </span>
          )
        )}
        {issue && copy && (
          <>
            <span className="hs-score-reviewbar__badge">
              {ja.reviewBadge.needsReview}
            </span>
            <span className="hs-score-reviewbar__reason">
              {copy.reasonTitle}
            </span>
            <span className="hs-score-reviewbar__detail">
              {copy.reasonDetail}
            </span>
            <span className="hs-score-reviewbar__meta">
              {copy.severityLabel}・{copy.statusLabel}
              {confidence != null &&
                `・${r.confidence(Math.round(confidence * 100))}`}
            </span>
          </>
        )}
      </div>
      <div
        className="hs-score-reviewbar__row"
        role="toolbar"
        aria-label={r.actionsLabel}
      >
        <HsTooltip content={withKey(ja.common.prev, "←")}>
          <HsButton size="small" disabled={total === 0} onClick={onPrev}>
            {ja.common.prev}
          </HsButton>
        </HsTooltip>
        <HsTooltip
          content={
            canPlaySource ? withKey(r.playSource, "R") : r.noAudibleRange
          }
        >
          <HsButton
            size="small"
            disabled={issue == null || !canPlaySource}
            onClick={onPlaySource}
          >
            {r.playSource}
          </HsButton>
        </HsTooltip>
        {action ? (
          <HsTooltip content={action.tooltip}>
            <HsButton size="small" onClick={() => action.run()}>
              {action.label}
            </HsButton>
          </HsTooltip>
        ) : null}
        <HsTooltip content={withKey(r.markOk, "O")}>
          <HsButton
            size="small"
            variant="primary"
            disabled={issue == null}
            onClick={onAccept}
          >
            {r.markOk}
          </HsButton>
        </HsTooltip>
        <HsTooltip content={withKey(r.dismiss, "Shift+O")}>
          <HsButton size="small" disabled={issue == null} onClick={onDismiss}>
            {r.dismiss}
          </HsButton>
        </HsTooltip>
        <HsTooltip content={noteEditTip(r.pitchUp, "Alt+↑")}>
          <HsButton
            size="small"
            disabled={issue == null || !canEditNotes}
            onClick={() => onPitch(1)}
          >
            {r.pitchUp}
          </HsButton>
        </HsTooltip>
        <HsTooltip content={noteEditTip(r.pitchDown, "Alt+↓")}>
          <HsButton
            size="small"
            disabled={issue == null || !canEditNotes}
            onClick={() => onPitch(-1)}
          >
            {r.pitchDown}
          </HsButton>
        </HsTooltip>
        <HsTooltip
          content={noteEditTip(
            noteDeleted ? r.restoreNote : r.deleteNote,
            "Delete",
          )}
        >
          <HsButton
            size="small"
            disabled={issue == null || !canEditNotes}
            onClick={onDeleteOrRestore}
          >
            {noteDeleted ? r.restoreNote : r.deleteNote}
          </HsButton>
        </HsTooltip>
        <HsTooltip content={withKey(r.undo, "Ctrl+Z")}>
          <HsButton size="small" disabled={!canUndo} onClick={onUndo}>
            {r.undo}
          </HsButton>
        </HsTooltip>
        <HsTooltip content={withKey(r.redo, "Ctrl+Shift+Z")}>
          <HsButton size="small" disabled={!canRedo} onClick={onRedo}>
            {r.redo}
          </HsButton>
        </HsTooltip>
        <HsTooltip content={withKey(ja.common.next, "→")}>
          <HsButton size="small" disabled={total === 0} onClick={onNext}>
            {ja.common.next}
          </HsButton>
        </HsTooltip>
        <HsTooltip content={withKey(r.nav.toggle, "I")}>
          <HsButton
            ref={navigatorButtonRef}
            size="small"
            icon={<List24Regular />}
            disabled={total === 0}
            onClick={onToggleNavigator}
            aria-pressed={navigatorOpen}
          >
            {r.nav.toggle}
          </HsButton>
        </HsTooltip>
        <span className="hs-score-reviewbar__spacer" />
        <HsTooltip content={withKey(r.exit, "Esc")}>
          <HsButton size="small" onClick={onExit}>
            {r.exit}
          </HsButton>
        </HsTooltip>
      </div>
      {!allDone && (
        <div className="hs-score-reviewbar__row hs-score-reviewbar__row--hint">
          <span className="hs-score-reviewbar__hint">{r.hint}</span>
        </div>
      )}
    </div>
  );
}

// @vitest-environment jsdom
/**
 * #361: ReviewNavigator — the filterable 要確認 issue list.
 *
 * Acceptance anchors: 全issue一覧 / 未解決のみ / severity・reason 絞り込み /
 * 任意issueへの直接ジャンプ / listbox keyboard semantics (↑↓ Enter Esc) /
 * screen-reader readable rows (position, reason, severity, status).
 */
import { act } from "react";
import { createRoot, type Root } from "react-dom/client";
import { afterEach, describe, expect, it, vi } from "vitest";
import { installJsdomStubs } from "../quality/testEnv";
import { ja } from "../strings/ja";
import type { ReviewCopy } from "./inspector";
import { ReviewNavigator, type ReviewNavigatorProps } from "./ReviewNavigator";
import type { ScoreReviewIssue } from "./review";

(globalThis as Record<string, unknown>).IS_REACT_ACT_ENVIRONMENT = true;
installJsdomStubs();

let root: Root | null = null;
let host: HTMLDivElement | null = null;

function issue(over: Partial<ScoreReviewIssue> = {}): ScoreReviewIssue {
  return {
    id: "ri-000001",
    scoreRevision: "rev-test",
    canonicalNoteIds: ["sn-000001"],
    timeRange: { startSec: 1.5, endSec: 2.0 },
    reason: "low_model_confidence",
    severity: "caution",
    evidence: {},
    status: "open",
    ...over,
  };
}

const ISSUES: readonly ScoreReviewIssue[] = [
  issue({ id: "ri-000001", canonicalNoteIds: ["sn-000001"] }),
  issue({
    id: "ri-000002",
    canonicalNoteIds: ["sn-000002", "sn-000003"],
    reason: "meter_conflict",
    severity: "warning",
    timeRange: { startSec: 62, endSec: 64.5 },
  }),
  issue({
    id: "ri-000003",
    canonicalNoteIds: ["sn-000004"],
    reason: "possible_triplet",
    severity: "info",
    status: "accepted",
    timeRange: { startSec: 95, endSec: 96 },
  }),
];

const COPY: ReviewCopy = {
  reasonTitle: (r) => ({
    low_model_confidence: "音低",
    meter_conflict: "拍子",
    possible_triplet: "三連",
  } as Record<string, string>)[r] ?? `other:${r}`,
  reasonDetail: () => "detail",
  severityLabel: (s) => ja.reviewSeverity[s] ?? s,
  statusLabel: (s) => ja.reviewStatus[s] ?? s,
};

function props(over: Partial<ReviewNavigatorProps> = {}): ReviewNavigatorProps {
  return {
    issues: ISSUES,
    activeIndex: 0,
    copy: COPY,
    onJump: vi.fn(),
    onClose: vi.fn(),
    ...over,
  };
}

async function mount(p: ReviewNavigatorProps): Promise<void> {
  host = document.createElement("div");
  document.body.appendChild(host);
  root = createRoot(host);
  await act(async () => {
    root!.render(<ReviewNavigator {...p} />);
  });
}

function options(): HTMLElement[] {
  return [...document.querySelectorAll('[role="option"]')] as HTMLElement[];
}

async function key(el: Element, k: string): Promise<void> {
  await act(async () => {
    el.dispatchEvent(
      new KeyboardEvent("keydown", { key: k, bubbles: true }),
    );
  });
}

afterEach(async () => {
  if (root) {
    await act(async () => {
      root!.unmount();
    });
    root = null;
  }
  host?.remove();
  host = null;
  document.body.innerHTML = "";
});

describe("ReviewNavigator (#361)", () => {
  it("未解決のみ defaults on — resolved rows hidden until unchecked", async () => {
    await mount(props());
    const list = options();
    expect(list).toHaveLength(2); // ri-000003 is accepted
    expect(list[0].textContent).toContain("音低");
    expect(list[1].textContent).toContain("拍子");

    const checkbox = document.querySelector<HTMLInputElement>(
      '.hs-reviewnav input[type="checkbox"]',
    )!;
    expect(checkbox.checked).toBe(true);
    await act(async () => {
      checkbox.click();
    });
    expect(options()).toHaveLength(3);
  });

  it("severity filter narrows the list", async () => {
    await mount(props());
    const selects = document.querySelectorAll("select");
    const severity = selects[0] as HTMLSelectElement;
    await act(async () => {
      const setter = Object.getOwnPropertyDescriptor(
        HTMLSelectElement.prototype,
        "value",
      )!.set!;
      setter.call(severity, "warning");
      severity.dispatchEvent(new Event("change", { bubbles: true }));
    });
    const list = options();
    expect(list).toHaveLength(1);
    expect(list[0].textContent).toContain("拍子");
    expect(list[0].textContent).toContain(ja.reviewSeverity.warning);
  });

  it("reason filter narrows the list", async () => {
    await mount(props({ activeIndex: 1 }));
    const selects = document.querySelectorAll("select");
    const reason = selects[1] as HTMLSelectElement;
    await act(async () => {
      const setter = Object.getOwnPropertyDescriptor(
        HTMLSelectElement.prototype,
        "value",
      )!.set!;
      setter.call(reason, "low_model_confidence");
      reason.dispatchEvent(new Event("change", { bubbles: true }));
    });
    expect(options()).toHaveLength(1);
    expect(options()[0].textContent).toContain("音低");
  });

  it("clicking a row jumps to its absolute issue index", async () => {
    const onJump = vi.fn();
    await mount(props({ onJump }));
    await act(async () => {
      options()[1].dispatchEvent(new MouseEvent("click", { bubbles: true }));
    });
    expect(onJump).toHaveBeenCalledWith(1); // absolute index, not row pos
  });

  it("listbox keyboard: ↑↓ moves, Enter jumps, Esc closes", async () => {
    const onJump = vi.fn();
    const onClose = vi.fn();
    await mount(props({ onJump, onClose }));
    const list = document.querySelector<HTMLElement>('[role="listbox"]')!;
    await key(list, "ArrowDown");
    expect(
      list.getAttribute("aria-activedescendant"),
    ).toBe("hs-reviewnav-opt-ri-000002");
    await key(list, "Enter");
    expect(onJump).toHaveBeenCalledWith(1);
  });

  it("Esc inside the panel closes the navigator, not the review", async () => {
    const onClose = vi.fn();
    await mount(props({ onClose }));
    const list = document.querySelector<HTMLElement>('[role="listbox"]')!;
    await key(list, "Escape");
    expect(onClose).toHaveBeenCalledOnce();
  });

  it("rows expose reason / severity / status / position to screen readers", async () => {
    await mount(props());
